class Solution:
    def countNonDecreasingArrays(self, digitSum):
        MOD = 10 ** 9 + 7
        L = [[] for _ in range(51)]
        for v in range(5001):
            t, sm = v, 0
            while t:
                sm += t % 10
                t //= 10
            L[sm].append(v)
        vals = L[digitSum[0]]
        if not vals:
            return 0
        cnt = [1] * len(vals)
        for s in digitSum[1:]:
            nv = L[s]
            if not nv:
                return 0
            nc = []
            i = run = 0
            for v in nv:
                while i < len(vals) and vals[i] <= v:
                    run = (run + cnt[i]) % MOD
                    i += 1
                nc.append(run)
            vals, cnt = nv, nc
        return sum(cnt) % MOD

