class Solution {
public:
    int countNonDecreasingArrays(vector<int>& digitSum) {
        const long long MOD = 1000000007LL;
        vector<vector<int>> L(51);
        for (int v = 0; v <= 5000; v++) {
            int t = v, s = 0;
            while (t) { s += t % 10; t /= 10; }
            L[s].push_back(v);
        }
        vector<int> vals = L[digitSum[0]];
        if (vals.empty()) return 0;
        vector<long long> cnt(vals.size(), 1);
        for (int k = 1; k < (int)digitSum.size(); k++) {
            vector<int>& nv = L[digitSum[k]];
            if (nv.empty()) return 0;
            vector<long long> nc;
            int i = 0; long long run = 0;
            for (int v : nv) {
                while (i < (int)vals.size() && vals[i] <= v) {
                    run = (run + cnt[i]) % MOD;
                    i++;
                }
                nc.push_back(run);
            }
            vals = nv; cnt = nc;
        }
        long long ans = 0;
        for (long long c : cnt) ans = (ans + c) % MOD;
        return (int)ans;
    }
};

