class Solution {
    public int countNonDecreasingArrays(int[] digitSum) {
        final long MOD = 1000000007L;
        List<List<Integer>> L = new ArrayList<>();
        for (int i = 0; i < 51; i++) L.add(new ArrayList<>());
        for (int v = 0; v <= 5000; v++) {
            int t = v, s = 0;
            while (t > 0) { s += t % 10; t /= 10; }
            L.get(s).add(v);
        }
        List<Integer> vals = L.get(digitSum[0]);
        if (vals.isEmpty()) return 0;
        long[] cnt = new long[vals.size()];
        Arrays.fill(cnt, 1);
        for (int k = 1; k < digitSum.length; k++) {
            List<Integer> nv = L.get(digitSum[k]);
            if (nv.isEmpty()) return 0;
            long[] nc = new long[nv.size()];
            int i = 0; long run = 0;
            for (int j = 0; j < nv.size(); j++) {
                int v = nv.get(j);
                while (i < vals.size() && vals.get(i) <= v) {
                    run = (run + cnt[i]) % MOD;
                    i++;
                }
                nc[j] = run;
            }
            vals = nv; cnt = nc;
        }
        long ans = 0;
        for (long c : cnt) ans = (ans + c) % MOD;
        return (int)ans;
    }
}

