var countNonDecreasingArrays = function(digitSum) {
    const MOD = 1e9 + 7;
    const L = Array.from({length: 51}, () => []);
    for (let v = 0; v <= 5000; v++) {
        let t = v, s = 0;
        while (t > 0) { s += t % 10; t = (t - t % 10) / 10; }
        L[s].push(v);
    }
    let vals = L[digitSum[0]];
    if (vals.length === 0) return 0;
    let cnt = vals.map(() => 1);
    for (let k = 1; k < digitSum.length; k++) {
        const nv = L[digitSum[k]];
        if (nv.length === 0) return 0;
        const nc = [];
        let i = 0, run = 0;
        for (const v of nv) {
            while (i < vals.length && vals[i] <= v) {
                run = (run + cnt[i]) % MOD;
                i++;
            }
            nc.push(run);
        }
        vals = nv; cnt = nc;
    }
    return cnt.reduce((a, b) => (a + b) % MOD, 0);
};
